import json
n=30
g=[[0]*n for _ in range(n)]
starts=[1,8,15,22,29]
tiles=[[3,2,2,3,4],[2,8,8,2,4],[3,2,2,3,4],[2,8,8,2,4],[4,4,4,4,4]]
for ti,r0 in enumerate(starts):
  for tj,c0 in enumerate(starts):
    color=tiles[ti][tj]
    for dr in range(5):
      for dc in range(5):
        r,c=r0+dr,c0+dc
        if r<n and c<n:
          g[r][c]= color if dr in (1,2,3) and dc in (1,2,3) else 4
# Connect matching-color tile centers across blank inter-tile gaps, using only zeros.
for color, tile_rows, tile_cols in [(3,[0,2],[0,3]),(8,[1,3],[1,2])]:
  for tr in tile_rows:
    r=starts[tr]+2
    for tc1,tc2 in [(min(tile_cols),max(tile_cols))]:
      c1,c2=starts[tc1]+2,starts[tc2]+2
      for c in range(c1+1,c2):
        if g[r][c]==0: g[r][c]=color
  for tc in tile_cols:
    c=starts[tc]+2
    r1,r2=starts[min(tile_rows)]+2,starts[max(tile_rows)]+2
    for r in range(r1+1,r2):
      if g[r][c]==0: g[r][c]=color
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))

